import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import{World}from'../world.js';import{floodCells}from'../architecture.js';
const w=new World(JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)))),rooms=w.data.scenes.filter(s=>s.household&&!s.originId);
test('every substantial interior has real architectural separation rather than an undivided prop box',()=>{const forms=new Set();for(const s of rooms){const h=s.household,p=h.architectureProgram;assert.equal(p.revision,7);forms.add(p.form);if(p.area>=35)assert.ok(h.partitions.length>=3,s.key+' missing separation');else assert.equal(p.form,'vestibule');for(const wall of h.partitions)assert.equal(s.floor[wall.y][wall.x],'#');}assert.ok(forms.size>=7);});
test('internal doorways are broad, unoccupied and connected to the actual arrival',()=>{let doors=0;for(const s of rooms){const seen=floodCells(s.floor,s.arrive);for(const d of s.household.architectureProgram.doorways){doors++;assert.ok(d.cells.length>=2);for(const [x,y]of d.cells){assert.equal(s.floor[y][x],'.',s.key+' doorway occupied');assert.ok(seen.has(x+','+y),s.key+' inaccessible doorway');}}}assert.ok(doors>60);});
test('house, clinic, archive, store and work hall are architecturally distinct and retain coherent uses',()=>{const forms=keys=>keys.map(k=>rooms.find(s=>s.key===k).household.architectureProgram.form);assert.deepEqual(forms(['home','clinic','guild','relief_store','pottery_floor']),['domestic','care-bays','records-wing','stockroom','work-bays']);for(const s of rooms){const p=s.household.architectureProgram;assert.equal(p.zones.length,3);assert.equal(new Set(p.zones.map(z=>z.role)).size,3);}});
